import type { EngineInterface as Engine } from 'claude-code'

import type { Entry } from '../../types'
import type { Context } from '../context'
import { inOrder } from '../core/entries'
import { globalSection, listingText } from '../core/listing'
import { formatCount, shortenText } from '../core/text'
import {
  addGlobalIdeas,
  forgetGlobalIdeas,
  loadEntries,
  loadGlobalIdeas,
  projectKeys,
  rankOf,
  refreshBand,
  saveEntries,
  saveGlobalEditing,
  saveGlobalIdea,
} from '../io/store'
import type { GlobalIdea } from '../io/store'
import { addEntries } from './capture'

const EMPTY = 'The global list is empty. Start a message with "+g" to add an idea to it.'

const isPlace = (n: number, length: number) => Number.isInteger(n) && n >= 1 && n <= length

const askPlaces = (length: number, count: number) => `Give ${count === 1 ? 'a number' : 'numbers'} from 1 to ${length}, as /aside g shows them.`

// The same idea in two places: an idea moved half-way, by a command that failed after its
// first write, is not moved a second time when the command runs again.
const isSame = (a: Entry, b: Entry) => a.at === b.at && a.text === b.text

// The global list as /aside g numbers it, in the order setting.
async function shownGlobal($: Engine, ctx: Context): Promise<GlobalIdea[]> {
  const ideas = await loadGlobalIdeas($)

  return ctx.settings.order === 'newest' ? ideas.reverse() : ideas
}

// What a command says it did to several ideas, or to one, by their text.
const sayIdeas = (done: string, entries: readonly Entry[]) =>
  entries.length === 1 ? `${done}: ${shortenText(entries[0]!.text, 60)}` : `${done} ${formatCount(entries.length, 'idea')}: ${entries.map(entry => shortenText(entry.text, 40)).join('; ')}`

// While Claude works, a command's text shows only after the turn: the list goes into the
// transcript at once instead.
export async function showGlobal($: Engine, ctx: Context): Promise<string> {
  const ideas = await shownGlobal($, ctx)
  const text = ideas.length === 0 ? EMPTY : listingText([globalSection(ideas.map(idea => idea.entry))])
  if (!ctx.session.isRunning || ideas.length === 0) {
    return text
  }
  $.ui.log(text)

  return 'Wrote the global list above while Claude was working.'
}

// /aside g here N ...: ideas from the global list to the end of this project's queue, into the
// queue first, so a failure between the writes leaves an idea in both, never in neither.
async function moveHere($: Engine, ctx: Context, numbers: readonly number[]): Promise<string> {
  const ideas = await shownGlobal($, ctx)
  if (ideas.length === 0) {
    return EMPTY
  }
  if (!numbers.every(n => isPlace(n, ideas.length))) {
    return askPlaces(ideas.length, numbers.length)
  }
  const chosen = [...new Set(numbers)].map(n => ideas[n - 1]!)
  const keys = await projectKeys($)
  const stored = await loadEntries($, keys.queue)
  // Typed as "+g idea", it is "+ idea" in the queue, so /aside edit keeps it here.
  const moved = chosen.map(({ entry }) => ({ text: entry.text, at: entry.at, kind: entry.kind, ...(entry.raw ? { raw: entry.raw.replace(/^\+g(?=\s)/, '+') } : {}) }))
  const fresh = moved.filter(entry => !stored.some(one => isSame(one, entry)))
  await saveEntries($, keys.queue, [...stored, ...fresh])
  await forgetGlobalIdeas($, chosen.map(idea => idea.key))
  await refreshBand($)

  return `${sayIdeas('Moved here', moved)} (${stored.length + fresh.length} waiting)`
}

// /aside g add N ...: ideas from this project's queue to the end of the global list, onto
// the list first, for the same reason. A comment stays in the queue.
async function moveToGlobal($: Engine, ctx: Context, numbers: readonly number[]): Promise<string> {
  const keys = await projectKeys($)
  const list = inOrder(await loadEntries($, keys.queue), ctx.settings.order)
  if (list.length === 0) {
    return 'The queue is empty.'
  }
  if (!numbers.every(n => isPlace(n, list.length))) {
    return `Give ${numbers.length === 1 ? 'a number' : 'numbers'} from 1 to ${list.length}, as /aside shows them.`
  }
  const comments = [...new Set(numbers)].filter(n => list[n - 1]!.kind !== 'idea')
  if (comments.length > 0) {
    return `Only ideas go to the global list; ${comments.join(', ')} ${comments.length === 1 ? 'is a comment' : 'are comments'}.`
  }
  const chosen = [...new Set(numbers)].map(n => list[n - 1]!)
  const there = await loadGlobalIdeas($)
  const now = await $.clock.now()
  const fresh = chosen.filter(entry => !there.some(idea => isSame(idea.entry, entry)))
  await addGlobalIdeas($, fresh.map(({ text, at }, i) => ({ text, at, kind: 'idea' as const, order: now + i / 1000 })))
  await saveEntries($, keys.queue, inOrder(list.filter(entry => !chosen.includes(entry)), ctx.settings.order))
  await refreshBand($)

  return sayIdeas('Moved to the global list', chosen)
}

async function removeGlobal($: Engine, ctx: Context, numbers: readonly number[]): Promise<string> {
  const ideas = await shownGlobal($, ctx)
  if (ideas.length === 0) {
    return EMPTY
  }
  if (!numbers.every(n => isPlace(n, ideas.length))) {
    return askPlaces(ideas.length, numbers.length)
  }
  const chosen = [...new Set(numbers)].map(n => ideas[n - 1]!)
  await forgetGlobalIdeas($, chosen.map(idea => idea.key))
  await refreshBand($)

  return sayIdeas('Removed from the global list', chosen.map(idea => idea.entry))
}

// /aside g pop [N]: the idea in the prompt box, ready to send, and off the list once it is
// there; the newest one unless named.
async function popGlobal($: Engine, ctx: Context, n?: number): Promise<string> {
  const ideas = await shownGlobal($, ctx)
  if (ideas.length === 0) {
    return EMPTY
  }
  const at = n ?? (ctx.settings.order === 'newest' ? 1 : ideas.length)
  if (!isPlace(at, ideas.length)) {
    return askPlaces(ideas.length, 1)
  }
  const idea = ideas[at - 1]!
  const filled = await $.prompt.fill({ text: idea.entry.text, mode: 'insert' })
  if (!filled.isFilled) {
    return 'The prompt box cannot take it now; the idea stays on the global list.'
  }
  await forgetGlobalIdeas($, [idea.key])
  await refreshBand($)

  return `In the prompt box, ready to send: ${shortenText(idea.entry.text, 60)}`
}

// /aside g edit N: as /aside edit does for the queue, the idea leaves the list for the prompt
// box as "+g idea", and the next message that is one "+g" idea takes its place again. The
// record is written before the idea leaves, so a failure between keeps it in both.
async function editGlobal($: Engine, ctx: Context, n: number): Promise<string> {
  const ideas = await shownGlobal($, ctx)
  if (ideas.length === 0) {
    return EMPTY
  }
  if (!isPlace(n, ideas.length)) {
    return askPlaces(ideas.length, 1)
  }
  const idea = ideas[n - 1]!
  const filled = await $.prompt.fill({ text: `+g ${idea.entry.text}`, mode: 'insert' })
  if (!filled.isFilled) {
    return 'The prompt box cannot take it now; the idea stays on the global list.'
  }
  await saveGlobalEditing($, idea)
  await forgetGlobalIdeas($, [idea.key])
  await refreshBand($)

  return `Global idea ${n} is in the prompt box: change it and press Enter; it goes back to place ${n}.`
}

// /aside g move N M: one write, to the idea moved, which takes a place between its new
// neighbours, so other sessions adding meanwhile are left alone. Neighbours too close to
// leave room between them are placed again, one after another, so the order shown is the
// order stored.
async function moveGlobal($: Engine, ctx: Context, from: number, to: number): Promise<string> {
  const ideas = await shownGlobal($, ctx)
  if (ideas.length < 2) {
    return 'Nothing to move.'
  }
  if (!isPlace(from, ideas.length) || !isPlace(to, ideas.length)) {
    return `Give two places from 1 to ${ideas.length}: /aside g move 3 1`
  }
  const [idea] = ideas.splice(from - 1, 1)
  ideas.splice(to - 1, 0, idea!)
  const stored = ctx.settings.order === 'newest' ? [...ideas].reverse() : ideas
  const i = stored.indexOf(idea!)
  const before = i > 0 ? rankOf(stored[i - 1]!) : undefined
  const after = i < stored.length - 1 ? rankOf(stored[i + 1]!) : undefined
  const order = before !== undefined && after !== undefined ? (before + after) / 2 : before !== undefined ? before + 1 : after! - 1
  const fits = (before === undefined || before < order) && (after === undefined || order < after)
  if (fits) {
    await saveGlobalIdea($, { key: idea!.key, entry: { ...idea!.entry, order } })
  } else {
    const start = rankOf(stored[0]!)
    for (const [k, one] of stored.entries()) {
      if (rankOf(one) !== start + k) await saveGlobalIdea($, { key: one.key, entry: { ...one.entry, order: start + k } })
    }
  }

  return listingText([globalSection(ideas.map(one => one.entry))])
}

const isNumbers = (words: readonly string[]) => words.length > 0 && words.every(word => /^\d+$/.test(word))

// /aside g ...: a command on the global list when the words have its shape, else an idea for
// it, as "+g TEXT" would.
export async function runGlobal($: Engine, ctx: Context, args: readonly string[]): Promise<string> {
  const [first, ...rest] = args
  const verb = first?.toLowerCase()
  const numbers = rest.map(Number)
  if (verb === undefined) {
    return showGlobal($, ctx)
  }
  if (verb === 'here' && isNumbers(rest)) {
    return moveHere($, ctx, numbers)
  }
  if (verb === 'add' && isNumbers(rest)) {
    return moveToGlobal($, ctx, numbers)
  }
  if ((verb === 'remove' || verb === 'rm') && isNumbers(rest)) {
    return removeGlobal($, ctx, numbers)
  }
  if (verb === 'edit' && rest.length === 1 && isNumbers(rest)) {
    return editGlobal($, ctx, numbers[0]!)
  }
  if (verb === 'pop' && (rest.length === 0 || (rest.length === 1 && isNumbers(rest)))) {
    return popGlobal($, ctx, numbers[0])
  }
  if ((verb === 'move' || verb === 'mv') && rest.length === 2 && isNumbers(rest)) {
    return moveGlobal($, ctx, numbers[0]!, numbers[1]!)
  }

  return (await addEntries($, ctx, `+g ${args.join(' ')}`, undefined, undefined, { report: 'none' })) ?? showGlobal($, ctx)
}

files.hooks/features/queue.ts:
import type { EngineInterface as Engine } from 'claude-code'

import type { Entry } from '../../types'
import type { Context } from '../context'
import { findTags, inOrder } from '../core/entries'
import { describeCount, isExportText, listingMarkdown, listingText, planSection, queueSection, tagsSection } from '../core/listing'
import type { ListingSection } from '../core/listing'
import { popPrompt } from '../core/prompts'
import { canonicalPath, formatCount, isAbsolutePath, isWindowsPath, relativePath, shortenText } from '../core/text'
import { resolveFile, tryReadFile, writeExport } from '../io/host'
import {
  bringBackTake,
  loadEntries,
  loadHanded,
  loadPlan,
  projectKeys,
  readTrackedFiles,
  refreshBand,
  saveEditing,
  saveEntries,
  saveTake,
  tagId,
  trackFile,
} from '../io/store'
import type { Keys } from '../io/store'

// The <!-- ? --> tags in the session's markdown files, as entries of their own; `onlyNew`
// leaves out those an earlier /aside already handed over.
export async function tagsInFiles($: Engine, onlyNew = false): Promise<Entry[]> {
  const { handed } = await projectKeys($)
  const old = new Set(onlyNew ? await loadHanded($, handed) : [])
  const found: Entry[] = []
  for (const file of await readTrackedFiles($)) {
    const source = await tryReadFile($, file)
    for (const tag of source === undefined ? [] : findTags(source)) {
      const entry: Entry = { text: tag.text, at: 0, kind: tag.kind, file, line: tag.line, isTag: true, ...(tag.quote ? { quote: tag.quote } : {}) }
      if (!old.has(tagId(entry))) found.push(entry)
    }
  }

  return found
}

// What /aside shows: the queue, the tags in files and the plan, with what each section holds.
async function loadListing($: Engine, ctx: Context) {
  const { root, queue, plan: planKey, handed } = await projectKeys($)
  const list = inOrder(await loadEntries($, queue), ctx.settings.order)
  const tags = await tagsInFiles($)
  const handedOver = new Set(await loadHanded($, handed))
  const plan = await loadPlan($, planKey)
  const steps = planSection(plan)
  const sections = [
    queueSection(list, root),
    ...(tags.length > 0 ? [tagsSection(tags, root, tag => handedOver.has(tagId(tag)))] : []),
    ...(steps ? [steps] : []),
  ]

  return { root, list, tags, plan, sections }
}

export async function currentListing($: Engine, ctx: Context): Promise<ListingSection[]> {
  return (await loadListing($, ctx)).sections
}

// Words joined as a sentence lists them: "a, b and c".
const joinWords = (words: readonly string[]) => (words.length < 2 ? words.join('') : `${words.slice(0, -1).join(', ')} and ${words.at(-1)}`)

// Why a FILE for /aside export would not land where its name says, if it would not: a home
// folder or a variable nobody expands, or a path spelled for another system.
const exportNameProblem = (name: string, root: string): string | undefined => {
  if (/^(?:~|\$|%[^%]+%)/.test(name)) {
    return 'Name a file in the project or by its full path, as ~, $HOME and %USERPROFILE% are not expanded: /aside export notes/queue.md'
  }
  if (!isWindowsPath(root)) {
    return isWindowsPath(name) || name.includes('\\') ? `${name} is spelled as on Windows; name the file as this system does, such as notes/queue.md.` : undefined
  }
  // On Windows a path with no drive starts at the drive's root, and any other ":" names a
  // stream inside a file.
  const isUnplaced = /^[\\/](?![\\/])/.test(name) || name.replace(/^[A-Za-z]:(?=[\\/])/, '').includes(':')

  return isUnplaced ? `${name} is not a full Windows path; name the file in the project or with its drive, such as C:\\notes\\queue.md.` : undefined
}

// Writes what /aside shows to a Markdown file in the project, aside.md unless named: over an
// earlier export, never over another file. The queue stays as it is.
export async function exportListing($: Engine, ctx: Context, name: string): Promise<string> {
  const { root, list, tags, plan, sections } = await loadListing($, ctx)
  if (list.length === 0 && tags.length === 0 && plan.steps.length === 0) {
    return 'Nothing to export: the queue is empty.'
  }
  const problem = exportNameProblem(name, root)
  if (problem) {
    return problem
  }
  const named = canonicalPath(name || 'aside.md', root)
  const path = isAbsolutePath(named) ? named : canonicalPath(`${root}/${named}`)
  const shown = relativePath(path, root)
  // In UTC: the clock gives the moment, not the person's time zone.
  const made = new Date(await $.clock.now()).toISOString().slice(0, 16).replace('T', ' ')
  const wrote = await writeExport($, path, listingMarkdown(sections, `${made} UTC`))
  if (!wrote.isWritten) {
    return 'isForeign' in wrote ? `${shown} is not an aside export; name another file: /aside export FILE` : `Could not write ${shown}: ${wrote.reason}.`
  }
  const what = [describeCount(list), tags.length > 0 ? formatCount(tags.length, 'tag') : '', plan.steps.length > 0 ? `the plan of ${formatCount(plan.steps.length, 'step')}` : '']

  return `Exported ${joinWords(what.filter(Boolean))} to ${shown}.`
}

// The pane the band's list button opens; register.tsx names the same id in its matcher.
export const LIST_PANE = 'aside'

// The list pane as the person sees it: not open, open but out of sight (a tab behind another
// pane, or waiting undrawn), or in sight.
async function listPaneState($: Engine): Promise<'closed' | 'hidden' | 'shown'> {
  const pane = (await $.ui.panes()).find(one => one.id === LIST_PANE)

  return pane === undefined ? 'closed' : pane.isShown && pane.isPlaced ? 'shown' : 'hidden'
}

// Shows the list pane: opens it, or brings it to the front when it is open out of sight. The
// reason is the surface's when it cannot place the pane.
export async function openListPane($: Engine): Promise<{ isPlaced: true } | { isPlaced: false; reason: string }> {
  if ((await listPaneState($)) === 'shown') {
    return { isPlaced: true }
  }

  return $.ui.open({ id: LIST_PANE, title: 'aside', focus: true, closeOnEscape: true })
}

// The band's list button: closes the list pane when it is in sight, shows it otherwise. A pane
// open out of sight is shown, not closed, or the press would seem to do nothing.
export async function toggleListPane($: Engine) {
  const state = await listPaneState($)
  if (state === 'shown') {
    await $.ui.close({ id: LIST_PANE })
    return
  }
  const opened = await openListPane($)
  // The engine's reason runs long ("unasked below 144 columns (125 now): placed when ..."): its head says enough.
  if (!opened.isPlaced) $.ui.toast(`Could not show the list pane (${opened.reason.split(':')[0]}); /aside shows the list`)
}

// /aside alone. While Claude works, what a command prints shows only once the turn ends, so
// the list opens in the pane, which shows at once and keeps up to date; where the terminal has
// no room for it, the list goes into the transcript as a line, which shows at once too.
export async function showListing($: Engine, ctx: Context): Promise<string> {
  const text = listingText(await currentListing($, ctx))
  if (!ctx.session.isRunning) {
    return text
  }
  if ((await openListPane($)).isPlaced) {
    return 'Opened the list in the pane while Claude was working.'
  }
  $.ui.log(text)

  return 'Wrote the list above while Claude was working.'
}

// The queue as /aside shows it: every number a command takes is a place in this list.
async function shownQueue($: Engine, ctx: Context) {
  const keys = await projectKeys($)

  return { keys, list: inOrder(await loadEntries($, keys.queue), ctx.settings.order) }
}

// Stores a list taken from shownQueue back in the order the store keeps, oldest first.
async function saveShownQueue($: Engine, ctx: Context, keys: Keys, list: readonly Entry[]) {
  await saveEntries($, keys.queue, inOrder(list, ctx.settings.order))
}

const isPlace = (n: number, length: number) => Number.isInteger(n) && n >= 1 && n <= length

export async function editEntry($: Engine, ctx: Context, n: number): Promise<string> {
  const { keys, list } = await shownQueue($, ctx)
  if (list.length === 0) {
    return 'The queue is empty.'
  }
  if (!isPlace(n, list.length)) {
    return `Give a number from 1 to ${list.length}, as /aside list shows them.`
  }
  const entry = list[n - 1]!
  const filled = await $.prompt.fill({ text: entry.raw ?? `+ ${entry.text}`, mode: 'insert' })
  if (!filled.isFilled) {
    return 'The prompt box cannot take it now; the entry stays in the queue.'
  }
  list.splice(n - 1, 1)
  await saveShownQueue($, ctx, keys, list)
  await saveEditing($, keys.editing, { index: n - 1, idea: entry })
  await refreshBand($)

  return `Entry ${n} is in the prompt box: change it and press Enter; it goes back to place ${n}, still pointing where it did.`
}

export async function moveEntry($: Engine, ctx: Context, from: number, to: number): Promise<string> {
  const { keys, list } = await shownQueue($, ctx)
  if (list.length < 2) {
    return 'Nothing to move.'
  }
  if (!isPlace(from, list.length) || !isPlace(to, list.length)) {
    return `Give two places from 1 to ${list.length}: /aside move 3 1`
  }
  const [entry] = list.splice(from - 1, 1)
  list.splice(to - 1, 0, entry!)
  await saveShownQueue($, ctx, keys, list)

  return listingText([queueSection(list, keys.root)])
}

// The newest entry, or entry `n`, taken out of the queue into the box, ready to send: no
// "+" in front, a comment with what it is about.
export async function popEntry($: Engine, ctx: Context, n?: number): Promise<string> {
  const { keys, list } = await shownQueue($, ctx)
  if (list.length === 0) {
    return 'The queue is empty.'
  }
  const at = n ?? (ctx.settings.order === 'newest' ? 1 : list.length)
  if (!isPlace(at, list.length)) {
    return `Give a number from 1 to ${list.length}, as /aside shows them.`
  }
  const entry = list[at - 1]!
  const filled = await $.prompt.fill({ text: popPrompt(entry, keys.root), mode: 'insert' })
  if (!filled.isFilled) {
    return 'The prompt box cannot take it now; the entry stays in the queue.'
  }
  list.splice(at - 1, 1)
  await saveShownQueue($, ctx, keys, list)
  await refreshBand($)

  return `In the prompt box, ready to send: ${shortenText(entry.text, 60)}`
}

// Removes the entries at places `numbers`, all of them or none when one is out of range.
export async function removeEntries($: Engine, ctx: Context, numbers: readonly number[]): Promise<string> {
  const { keys, list } = await shownQueue($, ctx)
  if (list.length === 0) {
    return 'The queue is empty.'
  }
  if (!numbers.every(n => isPlace(n, list.length))) {
    return `Give ${numbers.length === 1 ? 'a number' : 'numbers'} from 1 to ${list.length}, as /aside list shows them.`
  }
  const places = new Set(numbers)
  const gone = list.filter((_entry, i) => places.has(i + 1))
  await saveShownQueue($, ctx, keys, list.filter((_entry, i) => !places.has(i + 1)))
  await refreshBand($)

  return gone.length === 1 ? `Removed: ${gone[0]!.text}` : `Removed ${formatCount(gone.length, 'entry')}: ${gone.map(entry => shortenText(entry.text, 40)).join('; ')}`
}

export async function clearQueue($: Engine): Promise<string> {
  const keys = await projectKeys($)
  const stored = await loadEntries($, keys.queue)
  if (stored.length === 0) {
    return 'The queue is already empty.'
  }
  await saveTake($, keys, { entries: stored, tagIds: [], by: 'clear' })
  await saveEntries($, keys.queue, [])
  await refreshBand($)

  return `Cleared ${stored.length} entries. /aside undo brings them back.`
}

// Brings back what plan, run or clear took, unless a step of the plan is running in this
// session, so nothing is done twice.
export async function restoreTaken($: Engine): Promise<string> {
  const keys = await projectKeys($)
  const running = (await loadPlan($, keys.plan)).active
  if (running && running.sessionId === (await $.session.id())) {
    return `Step ${running.step + 1} of the plan is running; /aside stop first, so nothing is done twice.`
  }
  const { entries, tagIds } = await bringBackTake($, keys)
  if (entries.length === 0 && tagIds.length === 0) {
    return 'Nothing to bring back.'
  }
  const now = await refreshBand($, (await tagsInFiles($, true)).length)
  const back = [entries.length > 0 ? formatCount(entries.length, 'entry') : '', tagIds.length > 0 ? formatCount(tagIds.length, 'tag') : '']

  return `Brought back ${back.filter(Boolean).join(' and ')}, ${now.ideas + now.comments + now.tags} waiting.`
}

// Adds a file Claude did not write in this session to the files whose tags /aside reads.
export async function scanFile($: Engine, name: string): Promise<string> {
  if (name === '') {
    return 'Name a file: /aside scan docs/report.md'
  }
  const { root } = await projectKeys($)
  const file = await resolveFile($, name, root, await readTrackedFiles($))
  const source = await tryReadFile($, file)
  if (source === undefined) {
    return `Cannot read ${name}.`
  }
  if (isExportText(source)) {
    return `${relativePath(file, root)} is an aside export; its tags are read from the files it lists.`
  }
  await trackFile($, file)
  const found = findTags(source).length
  await refreshBand($, (await tagsInFiles($, true)).length)

  return `${relativePath(file, root)}: ${formatCount(found, 'tag')}; /aside includes the file from now on.`
}

files.hooks/ui/rows.tsx:
import type { Elements, RenderSurface } from 'claude-code'

import type { ListingSection } from '../core/listing'

// Where aside draws: the terminal and Claude Code Desktop. VS Code attaches no surface yet and
// the mobile app draws nothing a plugin draws, so there the engine draws its own.
const SURFACES: readonly RenderSurface[] = ['terminal', 'desktop']

export const isDrawnOn = (surface: RenderSurface) => SURFACES.includes(surface)

// The elements aside draws with; Box and Text are the same on every surface.
export type Drawing = Pick<Elements['terminal'], 'Box' | 'Text'>

// The colour of each kind, from the theme, so it suits light and dark alike.
const WORD_COLOURS: Record<string, string> = {
  idea: 'suggestion',
  question: 'warning',
  change: 'autoAccept',
  drop: 'error',
  'dig deeper': 'success',
}

// A step's mark on the plan's line, in its state's colour: done, running, still to do.
const STEP_MARKS: Record<string, { mark: string; colour?: string }> = {
  done: { mark: '●', colour: 'success' },
  running: { mark: '◉', colour: 'warning' },
  'to do': { mark: '○' },
}

// A section of steps, as planSection makes it: every row a step's state.
const isPlanSection = (section: ListingSection) => section.rows.length > 0 && section.rows.every(row => row.word in STEP_MARKS)

// The plan as a line of steps, top to bottom: each step's mark, its number and title, and
// under it, on the line that joins it to the next, what it took and what it said. A double
// line marks where a step paused the run.
const planRows = ({ Box, Text }: Drawing, section: ListingSection) => {
  const pausedAfter = /^Plan paused after step (\d+)/.exec(section.title)?.[1]

  return section.rows.map((row, n) => {
    const { mark, colour } = STEP_MARKS[row.word]!
    const isLast = n === section.rows.length - 1
    const join = row.label === pausedAfter ? '║' : isLast ? ' ' : '│'
    const under = [...row.lines.slice(1), ...row.about.map(about => `↳ ${about}`)].map(line => line.trim()).filter(line => line !== '')
    if (row.label === pausedAfter) under.push('paused here: /aside continue')

    return (
      <Box flexDirection="column" marginTop={n === 0 ? 1 : 0}>
        <Box>
          <Box width={3} flexShrink={0}>
            <Text color={colour} dimColor={colour === undefined}>{mark}</Text>
          </Box>
          <Box width={4} flexShrink={0}>
            <Text dimColor>{row.label}</Text>
          </Box>
          <Box flexShrink={1}>
            <Text dimColor={row.word === 'done'}>{row.lines[0]?.trim() ?? ''}</Text>
            {row.word === 'running' ? <Text> </Text> : null}
            {row.word === 'running' ? <Text color="warning">running</Text> : null}
          </Box>
        </Box>
        {under.map(line => (
          <Box>
            <Box width={7} flexShrink={0}>
              <Text dimColor>{join}</Text>
            </Box>
            <Box flexShrink={1}>
              <Text dimColor>{line}</Text>
            </Box>
          </Box>
        ))}
      </Box>
    )
  })
}

// The sections of a listing: the queue and the tags in columns, number, kind in its colour,
// then the text, wrapped in its own column, and what it is about; the plan as a line of
// steps. Each line is drawn trimmed and blank ones are left out, as they are when the
// listing is read back from the printed text.
export const listingRows = (ui: Drawing, sections: readonly ListingSection[]) =>
  sections.map((section, i) => {
    const { Box, Text } = ui
    const width = Math.max(0, ...section.rows.map(row => row.word.length))

    return (
      <Box flexDirection="column" marginTop={i === 0 ? 0 : 1}>
        <Box>
          {i === 0 ? <Text bold color="claude">aside  </Text> : null}
          <Text bold>{section.title}</Text>
        </Box>
        {isPlanSection(section)
          ? planRows(ui, section)
          : section.rows.map((row, n) => (
              <Box marginTop={n === 0 ? 1 : 0}>
                <Box width={5} flexShrink={0}>
                  <Text dimColor>{row.label.padStart(3)}</Text>
                </Box>
                <Box width={width + 2} flexShrink={0}>
                  <Text color={WORD_COLOURS[row.word] ?? 'text'}>{row.word}</Text>
                </Box>
                <Box flexDirection="column" flexShrink={1}>
                  {row.lines
                    .map(line => line.trim())
                    .filter(line => line !== '')
                    .map(line => (
                      <Text dimColor={row.word === 'done'}>{line}</Text>
                    ))}
                  {row.about.map(about => (
                    <Text dimColor>{`↳ ${about}`}</Text>
                  ))}
                </Box>
              </Box>
            ))}
      </Box>
    )
  })

files.types/index.d.ts:
// What a queued entry is: a plain idea, or a comment on something the agents wrote.
export type Kind = 'idea' | 'question' | 'change' | 'drop' | 'deeper'

export type Entry = {
  text: string
  // The line as typed, "+" included: what /aside edit puts back in the prompt box.
  raw?: string
  at: number
  kind: Kind
  file?: string
  line?: number
  heading?: string
  quote?: string
  // The quoted text was kept, but no file holds it; `from` says where it came from.
  isLoose?: true
  from?: 'terminal' | 'clipboard'
  // What the last tool printed when the comment came (an error first), for context.
  output?: string
  // The task that was running, and the branch, when the entry came.
  task?: string
  branch?: string
  // Read from a <!-- ? --> tag in a file, not typed at the prompt.
  isTag?: true
}

export type Step = {
  title: string
  prompt: string
  isDone?: true
  // What the step's answer said it did and left open (its "Result:" line), and how long it
  // ran, kept once it is done for the summary at the end of the run.
  result?: string
  ms?: number
}

export type Plan = {
  steps: Step[]
  // The step running now: isChain runs the next one when it ends, turnId names its turn
  // once it started, sessionId the session that runs it (the store is shared by all), and
  // pausedFor what Claude asked for when it paused the plan from this step, and then the
  // steps still to run after it when /aside run named them (in place of the chain).
  active?: { step: number; isChain: boolean; turnId?: string; sessionId: string; pausedFor?: string; then?: number[] }
  // A run a step paused with the wait tool: the step that paused it, why, and how the run
  // was to go on (as a chain, or with the steps /aside run named), until it goes on or stops.
  paused?: { step: number; reason: string; isChain: boolean; then?: number[] }
}

export type Band = { ideas: number; comments: number; tags: number; steps: number; done: number; running?: number; paused?: number; global?: number }

declare module 'claude-code' {
  interface PluginState {
    'aside': { band: Band; files: string[] }
  }
}
